    "effect": "[登場時]\nこのキャラが自分の手札から登場していた場合、APを1支払ってもよい。そうした場合、カードを1枚引く。その後、自分の手札の〈シンデレラ〉を1枚リムーブエリアに置いてもよい。そうした場合、そのカードの\n[トリガー]\nを発動する。",
    "effectZh": "[登场时]\n当此角色从自己手札中登场时，可以选择支付 1 AP。\n如此操作的话，抽牌 1 张。之后，也可以选择将手札中的〈Cinderella〉置入移除区。\n如此操作的话，发动该卡片的\n[Trigger]",
    "trigger": "[アクティブ]\n自分の場のキャラを1枚選び、アクティブにし、このターン中、BP+3000。",
    "triggerZh": "[激活]\n选择自己场上的角色 1 枚，将其激活并赋予本回合中 BP+3000。",
