    "effect": "[レイド]\n〈グレイブ〉アクティブにし、フロントLに移動できる\n[登場時]\n自分の山札の上から2枚をリムーブエリアに置く。自分の手札を1枚リムーブエリアに置いてもよい。そうした場合、自分のリムーブエリアから必要エナジーが『0』以下で消費APが1の黄の［特徴：オールドテイルズ］を1枚まで自分の場にレストで登場させる。自分のターン中なら、自分のリムーブエリアにあるカード1枚につき、この効果で登場させるキャラの必要エナジーの範囲+1。",
    "effectZh": "[Raid]\n将〈Grave〉激活并移动至前线 L\n[登场时]\n将自己山札上方的 2 张置入移除区。也可以选择将手札中的 1 张置入移除区。\n如此操作的话，从自己移除区中最多召唤 1 张必要能量为『0』以下且消耗 AP 为 1 的黄的［特征：旧尾］至场上（横置状态）。若处于自己的回合内，则每有 1 张位于自己移除区的卡片，此效果所召唤角色的必要能量范围 +1。",
    "trigger": "[レイド]\nこのカードを手札に加えるか、必要エナジーを満たしている場合、レイドさせる。",
    "triggerZh": "[Raid]\n将此卡加入手札或满足必要能量时，发动 Raid。",
